-- Admin-editable curriculum: the course catalog, the 4-year study plan, and
-- the four major-elective tracks.
--
-- src/lib/curriculumData.js and src/lib/courseDescriptions.js stay: they seed
-- these tables and remain the runtime fallback for CurriculumRoadmap.jsx. See
-- the "Admin-editable content" section of CLAUDE.md.
--
-- Why name and credits are denormalized into the two list tables rather than
-- joined from site_courses:
--
--   The study plan contains 7 placeholder rows the curriculum itself uses for
--   "student chooses one" slots -- 'EN XX XXXX' (four times, with different
--   credit values), 'XX XXXX', and 'IC 011 10X'. The elective tracks contain 4
--   rows whose code is literally 'EN [unclear]', flagged in the source data
--   where a screenshot was obscured. Neither set can be a row in site_courses:
--   the codes repeat, so they cannot be a primary key, and none of them have a
--   description. Carrying name and credits on the list row is what lets those
--   entries render at all.
--
--   The '[unclear]' markers are load-bearing, not dirty data. They mean "verify
--   this code against the official KKU curriculum before publishing". Do not
--   tidy them away.

create table site_courses (
  code text primary key,
  name text not null,
  credits text,
  description_en text not null default '',
  description_th text not null default '',
  prerequisites text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table site_study_plan (
  id uuid primary key default gen_random_uuid(),
  year integer not null check (year between 1 and 4),
  -- 'Semester 1' | 'Semester 2' | 'Summer'. Sorted lexically, which happens to
  -- put Summer last, so no separate ordering column is needed.
  semester_name text not null,
  -- Cumulative credits by the end of that semester. Null for Summer, which the
  -- source course map leaves blank.
  total_accumulated integer,
  -- Not a foreign key to site_courses: placeholder codes have no course row.
  course_code text not null,
  course_name text not null,
  credits text,
  course_type text not null,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table site_elective_courses (
  id uuid primary key default gen_random_uuid(),
  track text not null,
  course_code text not null,
  course_name text not null,
  credits text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index site_study_plan_order_idx on site_study_plan (year, semester_name, sort_order);
create index site_elective_courses_order_idx on site_elective_courses (track, sort_order);

alter table site_courses enable row level security;
alter table site_study_plan enable row level security;
alter table site_elective_courses enable row level security;

create policy "courses are viewable by everyone" on site_courses
  for select using (true);

create policy "study plan is viewable by everyone" on site_study_plan
  for select using (true);

create policy "elective courses are viewable by everyone" on site_elective_courses
  for select using (true);

-- Seed: 75 courses, joining names and credits from curriculumData.js with the
-- bilingual descriptions from courseDescriptions.js (official TQF.2 / mco.2).

-- Seed: 39 study-plan rows, from the 2026 Course Map.

-- Seed: 48 elective-track rows across AI / Digital Media / Interactive / Software.
